package io.coldchain;
import java.io.*;
import java.util.*;

// Kafka client security. In the deployment every service gets its own principal's client configuration (TLS truststore,
// SASL mechanism and credentials) as a file, KAFKA_CLIENT_CONFIG, generated by the keys service into a volume and mounted
// read-only for that service alone (ops/security/init.sh). Unset (tests), clients connect without security.
final class KafkaClients {
 private KafkaClients() {}
 static Map<String,String> config() {
  String file=System.getenv("KAFKA_CLIENT_CONFIG");
  if(file==null||file.isBlank())return Map.of();
  Properties p=new Properties();
  try(Reader r=new FileReader(file)){p.load(r);}catch(IOException e){throw new UncheckedIOException("cannot read Kafka client configuration "+file,e);}
  Map<String,String> out=new TreeMap<>();
  p.stringPropertyNames().forEach(k->out.put(k,p.getProperty(k)));
  return out;
 }
 // The same settings as Spark Kafka source options.
 static Map<String,String> sparkOptions() {
  Map<String,String> out=new TreeMap<>();
  config().forEach((k,v)->out.put("kafka."+k,v));
  return out;
 }
}
